use core.files as files
use core.process as process
use core.text as text
use core.encoding.json as json

struct Report {
    count: Int
    name: String
    note: String
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    source :: files.read(path) ?? panic("read failed")
    count := 0
    name := ""
    note := ""
    have_count := false
    have_name := false
    have_note := false

    loop line in source.lines() {
        if line.trim().is_empty() -> next
        fields :: text.splitn(~line, "\t", 2)
        if fields.len() != 2 -> panic("malformed report field")
        key :: fields.get(0) ?? panic("malformed report field")
        value :: fields.get(1) ?? panic("malformed report field")
        if key == "count" {
            if have_count -> panic("duplicate count")
            count = Int.parse(value) ?? panic("invalid count")
            have_count = true
            next
        }
        if key == "name" {
            if have_name -> panic("duplicate name")
            name = value
            have_name = true
            next
        }
        if key == "note" {
            if have_note -> panic("duplicate note")
            note = value
            have_note = true
            next
        }
        panic("unknown report field {key}")
    }
    if !have_count || !have_name || !have_note -> panic("missing report field")

    report :: Report{count: count, name: name, note: note}
    name_json :: json.to_string(report.name)
    note_json :: json.to_string(report.note)
    print("{{\"count\":{report.count},\"name\":{name_json},\"note\":{note_json}}}")
}
